import React, { useState, useEffect, useCallback, memo } from 'react';
import { TrendingUp, Sparkles, BarChart3, Clock } from 'lucide-react';

// Composant pour les particules flottantes (memoïsé pour la performance)
const FloatingParticles = memo(() => (
  <div className="absolute inset-0 overflow-hidden pointer-events-none">
    {Array.from({ length: 5 }).map((_, i) => (
      <div
        key={i}
        className="absolute w-1 h-1 bg-white/30 rounded-full animate-float"
        style={{
          left: `${Math.random() * 100}%`,
          top: `${Math.random() * 100}%`,
          animationDelay: `${i * 0.5}s`,
          animationDuration: `${15 + Math.random() * 10}s`,
        }}
      />
    ))}
  </div>
));

FloatingParticles.displayName = 'FloatingParticles';

// Composant pour l'effet de brillance
const ShineEffect = memo(() => (
  <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000 pointer-events-none" />
));

ShineEffect.displayName = 'ShineEffect';

const WelcomeBanner = () => {
  const [currentTime, setCurrentTime] = useState('');
  const [isHovered, setIsHovered] = useState(false);

  // Génération des salutations
  const greetings = React.useMemo(() => [
    {
      text: "Bon retour, Enzo ! 👋",
      emoji: "👋",
      delay: 5000
    },
    {
      text: "Bonne journée, Enzo ! 🌟",
      emoji: "🌟",
      delay: 5000
    },
    {
      text: "Ravi de vous revoir, Enzo ! 🚀",
      emoji: "🚀",
      delay: 5000
    },
    {
      text: "Vos performances sont excellentes ! 📈",
      emoji: "📈",
      delay: 3000
    }
  ], []);

  const [greetingIndex, setGreetingIndex] = useState(0);

  // Mise à jour de l'heure
  useEffect(() => {
    const updateTime = () => {
      const now = new Date();
      setCurrentTime(now.toLocaleTimeString('fr-FR', { 
        hour: '2-digit', 
        minute: '2-digit',
        hour12: false
      }));
    };

    updateTime();
    const interval = setInterval(updateTime, 30000); // Mise à jour toutes les 30 secondes

    return () => clearInterval(interval);
  }, []);

  // Rotation des salutations avec useCallback
  useEffect(() => {
    const interval = setInterval(() => {
      setGreetingIndex(prev => (prev + 1) % greetings.length);
    }, greetings[greetingIndex].delay);

    return () => clearInterval(interval);
  }, [greetingIndex, greetings]);

  // Gestionnaire pour le bouton de rapport
  const handleViewReport = useCallback(() => {
    // Ici, vous pourriez ajouter une logique de navigation ou d'ouverture de modal
    console.log('Ouverture du rapport détaillé');
    // Exemple : router.push('/dashboard/reports');
  }, []);

  const currentGreeting = greetings[greetingIndex];

  // Statistiques (pourrait venir d'une API)
  const stats = {
    growth: "+12%",
    period: "cette semaine",
    lastLogin: currentTime,
    activeUsers: "1.2k"
  };

  return (
    <div 
      className="mb-6 sm:mb-8 rounded-2xl bg-gradient-to-r from-primary-500 via-primary-600 to-secondary-500 p-4 sm:p-6 text-white shadow-lg relative overflow-hidden animate-fade-in group hover:shadow-xl transition-all duration-300"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      role="banner"
      aria-label="Tableau de bord de bienvenue"
    >
      {/* Effets visuels */}
      <ShineEffect />
      <FloatingParticles />

      {/* Gradient overlay pour meilleur contraste */}
      <div className="absolute inset-0 bg-gradient-to-br from-black/10 to-transparent pointer-events-none" />

      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between relative z-10">
        {/* Section de gauche : Salutation et infos */}
        <div className="space-y-3 flex-1">
          <div className="flex items-center gap-3">
            <div className={`transition-all duration-500 ease-out transform ${isHovered ? 'scale-110' : 'scale-100'}`}>
              <Sparkles className="h-6 w-6 text-yellow-300 animate-pulse-gentle" aria-hidden="true" />
            </div>
            <div className="overflow-hidden">
              <h1 
                className="text-xl sm:text-2xl lg:text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-yellow-100 transition-all duration-500 ease-in-out transform group-hover:translate-x-1"
                key={greetingIndex}
                aria-live="polite"
              >
                {currentGreeting.text}
              </h1>
            </div>
          </div>

          <p className="text-sm sm:text-base opacity-90 animate-slide-up font-medium">
            Voici ce qui se passe dans votre boutique aujourd'hui.
          </p>

          {/* Statistiques en ligne */}
          <div className="flex flex-wrap gap-2 mt-3">
            <div 
              className="flex items-center gap-2 px-3 py-2 bg-white/15 rounded-xl backdrop-blur-sm border border-white/20 hover:bg-white/20 transition-all duration-300 animate-slide-in"
              style={{animationDelay: '0.2s'}}
              role="status"
              aria-label={`Croissance de ${stats.growth} ${stats.period}`}
            >
              <TrendingUp className="h-4 w-4 text-green-300" aria-hidden="true" />
              <span className="text-xs sm:text-sm font-semibold">
                <span className="text-green-300">{stats.growth}</span> de croissance {stats.period}
              </span>
            </div>

            <div 
              className="flex items-center gap-2 px-3 py-2 bg-white/10 rounded-xl backdrop-blur-sm border border-white/20 hover:bg-white/15 transition-all duration-300 animate-slide-in"
              style={{animationDelay: '0.3s'}}
            >
              <div className="flex items-center gap-1">
                <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse" aria-hidden="true" />
                <span className="text-xs sm:text-sm font-medium">
                  {stats.activeUsers} utilisateurs actifs
                </span>
              </div>
            </div>
          </div>
        </div>

        {/* Section de droite : Actions et informations */}
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3 min-w-fit">
          {/* Indicateur de dernière connexion */}
          <div 
            className="flex items-center gap-3 px-4 py-3 bg-white/15 rounded-xl backdrop-blur-sm border border-white/25 hover:bg-white/20 transition-all duration-300 animate-slide-up group/last-login"
            style={{animationDelay: '0.3s'}}
            role="timer"
            aria-label={`Dernière connexion à ${stats.lastLogin}`}
          >
            <div className="relative">
              <Clock className="h-4 w-4 text-blue-200" aria-hidden="true" />
              <div className="absolute inset-0 animate-ping-slow opacity-20">
                <Clock className="h-4 w-4 text-blue-200" aria-hidden="true" />
              </div>
            </div>
            <div className="flex flex-col">
              <span className="text-xs opacity-80">Dernière connexion</span>
              <span className="text-sm font-semibold">{stats.lastLogin}</span>
            </div>
          </div>

          {/* Bouton d'action principal */}
          <button 
            onClick={handleViewReport}
            className="px-4 sm:px-5 py-3 bg-gradient-to-r from-white to-gray-100 text-primary-700 font-semibold rounded-xl hover:from-gray-100 hover:to-white transition-all duration-300 transform hover:scale-[1.02] active:scale-[0.98] shadow-lg hover:shadow-xl flex items-center justify-center gap-2 animate-slide-up hover:shadow-white/20 focus:outline-none focus:ring-2 focus:ring-white/50 focus:ring-offset-2 focus:ring-offset-primary-600"
            style={{animationDelay: '0.4s'}}
            aria-label="Voir le rapport détaillé des performances"
          >
            <BarChart3 className="h-5 w-5" aria-hidden="true" />
            <span className="whitespace-nowrap">Voir rapport</span>
          </button>
        </div>
      </div>

      {/* Indicateur de progression (optionnel) */}
      <div className="absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r from-transparent via-white/30 to-transparent">
        <div 
          className="h-full bg-white/50 transition-all duration-1000 ease-out"
          style={{ width: `${((greetingIndex + 1) / greetings.length) * 100}%` }}
        />
      </div>
    </div>
  );
};

// Optimisation des performances avec memo
export default memo(WelcomeBanner);
